//! 🧭️ A bounded ordinal walk retains one authentic resident source and its address across native turns.
use super::*;
/// 🗂️ Returning a row closes every source alias before the next real resident is selected.
pub struct OriginalToolLedgerWalk<S:RetireOwned+Send+Sync+'static>{read:OriginalToolLedgerRead<S>,after:Option<SharedUtf8>,displaced:Option<SharedUtf8>,addresses:RetainedCloneClose,binding:Option<(OriginalSourceBinding,(u64,u64))>,revision:u64,returning:bool,saved:bool,done:bool,closing:bool}
impl<S:RetireOwned+Send+Sync+'static> Default for OriginalToolLedgerWalk<S>{fn default()->Self{Self{read:Default::default(),after:None,displaced:None,addresses:Default::default(),binding:None,revision:0,returning:false,saved:false,done:false,closing:false}}}
impl<S:RetireOwned+Send+Sync+'static> OriginalToolLedgerWalk<S>{
 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if self.binding.is_some_and(|(binding,decoder)|!binding.matches(cx)||cx.native_receiving_identity()!=Some(decoder)){return Err(invalid("original tool traversal changed its caller or decoder"))}Ok(())}
 fn addresses_pending(&self)->bool{self.displaced.is_some()||!self.addresses.is_empty()}
 fn address_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.addresses.next_owner_demands::<SharedUtf8>(self.displaced.is_some(),&None,body)}
 fn close_addresses(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=self.address_demands(4096)?;semio_framework_job::close_original_retained_step(cx,d,|g|{if self.addresses.is_empty(){Ok(self.addresses.begin_granted(&mut self.displaced,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}else{self.addresses.select(4096)?.step(g)}})?;Ok(())}
 /// 📏️ Quotes one real source row, immutable read or original address closure.
 pub fn demands<L:OriginalToolLedgerSource<State=S>>(&self,ledger:&L,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands(ledger,body)}if self.binding.is_none(){return Ok(header::<(Option<(OriginalSourceBinding,(u64,u64))>,u64)>())}if self.addresses_pending(){return self.address_demands(body)}if self.returning{if !self.saved{return Ok(header::<(Option<SharedUtf8>,Option<SharedUtf8>,bool)>())}if self.read.terminal_is_empty(){return Ok(header::<(OriginalToolLedgerRead<S>,bool,bool)>())}return self.read.close_demands(ledger,body)}if self.done||self.ready(){return Ok(Default::default())}if self.read.binding.is_some(){return self.read.demands(ledger,body)}let Some((window,key))=ledger.original_next(self.after.as_deref())else{return Ok(header::<bool>())};if !ledger.original_live(window,key)?{return Ok(header::<(Option<SharedUtf8>,Option<SharedUtf8>)>())}Ok(OriginalToolLedgerRead::<S>::admission_demands())}
 /// 🪜️ Selects at most one resident or immutable source fragment without collecting a key list.
 pub fn advance<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&mut L,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid("original tool traversal is closing").into())}if self.binding.is_none(){let binding=OriginalSourceBinding::borrow(cx);let d=self.demands(ledger,4096)?;let mut output=None;semio_framework_job::admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:1},|native|{self.binding=Some((binding,(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(||invalid("original tool traversal requires its actual decoder"))?)));self.revision=ledger.original_revision();Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}if ledger.original_revision()!=self.revision{return Err(invalid("original tool traversal requires its unchanged source frontier").into())}if self.addresses_pending(){self.close_addresses(cx)?;return Ok(false)}if self.returning{if !self.saved{let d=self.demands(ledger,4096)?;paid(cx,d,|_|{self.displaced=self.after.replace(self.read.window.as_ref().unwrap().clone());self.saved=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if !self.read.terminal_is_empty(){self.read.close_step(ledger,cx)?;return Ok(false)}let d=self.demands(ledger,4096)?;paid(cx,d,|_|{self.read=Default::default();self.returning=false;self.saved=false;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if self.done||self.ready(){return Ok(true)}if self.read.binding.is_some(){self.read.advance(ledger,cx)?;return Ok(self.ready())}let Some((window,key))=ledger.original_next(self.after.as_deref())else{let d=header::<bool>();paid(cx,d,|_|{self.done=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(self.done)};if !ledger.original_live(window,key)?{let d=header::<(Option<SharedUtf8>,Option<SharedUtf8>)>();paid(cx,d,|_|{self.displaced=self.after.replace(window.clone());Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}self.read.admit(ledger,window,key,cx)?;Ok(false)}
 /// 📖️ Lends the exact original state of the selected ready resident.
 pub fn borrow<'a,L:OriginalToolLedgerSource<State=S>>(&self,ledger:&'a L)->Result<RetainedCloneRef<'a,S>,ValueError>{if !self.ready(){return Err(invalid("original tool traversal row is incomplete"))}self.read.borrow(ledger)}
 /// 🪪️ The same sealed resident key and original address identify a ready source.
 pub fn resident(&self)->Option<(&SharedUtf8,RetainedOriginalSlotKey)>{self.ready().then(||(self.read.window.as_ref().unwrap(),self.read.key.unwrap()))}
 /// ✅️ Only one complete immutable resident is exposed at a time.
 pub fn ready(&self)->bool{self.read.ready()&&!self.returning&&!self.closing}
 /// 🧾️ The bounded walk exhausted its genuine resident index.
 pub fn done(&self)->bool{self.done&&!self.closing}
 /// 📏️ Quotes the actual row-return decision for an enclosing native cursor event.
 pub fn return_demands()->RetirementDemand{header::<bool>()}
 /// 📤️ Records the same ready source return under the enclosing original event's exact grant.
 pub fn finish_row_granted(&mut self,g:RetainedCloneGrant)->Result<Option<RetainedCloneProgress>,ValueError>{if !self.ready(){return Err(invalid("original tool traversal requires its complete row before return"))}let d=Self::return_demands();if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(None)}self.returning=true;Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 /// 📤️ Records the original row return after all projected leaves have closed.
 pub fn finish_row(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.ready(){return Err(invalid("original tool traversal requires its complete row before return").into())}let d=header::<bool>();paid(cx,d,|_|{self.returning=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})}
 /// 📏️ Quotes closure while allowing an independently changed global source frontier.
 pub fn close_demands<L:OriginalToolLedgerSource<State=S>>(&self,ledger:&L,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if self.read.binding.is_some()||!self.read.terminal_is_empty()&&self.read.closing{return self.read.close_demands(ledger,body)}if self.addresses_pending(){return self.address_demands(body)}if self.after.is_some(){return Ok(header::<(Option<SharedUtf8>,Option<SharedUtf8>)>())}if self.binding.is_some(){return Ok(header::<Option<(OriginalSourceBinding,(u64,u64))>>())}Ok(Default::default())}
 /// ♻️ Issued original state leases return before the traversal's address and caller fence close.
 pub fn close_step<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&mut L,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands(ledger,4096)?;if !self.closing{close_paid(cx,d,|_|{self.closing=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if self.read.binding.is_some()||!self.read.terminal_is_empty()&&self.read.closing{self.read.close_step(ledger,cx)?;return Ok(false)}if self.addresses_pending(){self.close_addresses(cx)?;return Ok(false)}if self.after.is_some(){close_paid(cx,d,|_|{self.displaced=self.after.take();Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if self.binding.is_some(){close_paid(cx,d,|_|{self.binding=None;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}Ok(true)}
 /// 🧺️ No issued source, captured issuer or original address remains.
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.binding.is_none()&&self.read.binding.is_none()&&self.after.is_none()&&self.displaced.is_none()&&self.addresses.is_empty()}
}
impl<S:RetireOwned+Send+Sync+'static> Drop for OriginalToolLedgerWalk<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty()||self.binding.is_none()&&!self.closing,"original tool traversal requires funded source closure")}}
